, "التضامن من أهم قيم المواطنة"]], ["رصيد لغوي", ["كرب: حزن وغم، الطوى: الجوع", "الخز: نسيج من الحرير", "الفاقرة: المصيبة الشديدة، آصرة: رابطة قوية"]]], "K": "قصيدة توجيهية يخاطب فيها الشاعر الأغنياء ليرحموا الفقراء، مستعينًا بالنداء والعتاب ووصف مأساة الطفل.", "M": ["حدّد المخاطَب وسبب النداء وغايته", "استخرج صيغ الأمر والنهي والنداء والاستفهام", "استخرج مؤشرات الوصف: صفات وحالات", "لاحظ الضمير الغالب وعلاقته بالاتساق"], "X": "الشاعر ينادي الأغنياء الذين يعيشون في رفاهية وينسون الفقراء الجوعى. يصف لهم طفلًا يتألم من الجوع وأمه حائرة، ثم يترك الطفل يتكلم ليحرّك قلوبهم. أراد الشاعر أن يدفعنا إلى مساعدة المحتاجين وألا نبقى غير مبالين.", "EX": [["إلى من يوجّه الشاعر نداءه ولماذا؟", "يوجّهه إلى الأغنياء المترفين. لأنهم قادرون على مساعدة الفقراء وغافلون عنهم. غايته إثارة رحمتهم."], ["اذكر مؤشرين للنمط التوجيهي في القصيدة.", "النداء مثل «يا أيها الرافعون القصور». الاستفهام مثل «ألا تسمعون ألا تبصرون». وكذلك الأمر في «أعزّوا كرامتي»."], ["هل غلب الأسلوب الخبري أم الإنشائي؟ وما أثر ذلك؟", "غلب الإنشائي. لأن القصد حثّ المخاطبين على الفعل. فيحقق انسجام الخطاب مع غرضه."]]}, {"m": 3, "w": 3, "t": "الظاهرة اللغوية: الممنوع من الصرف", "pg": "ص 52", "i": "✍️", "B": [["المفهوم", ["الاسم الممنوع من الصرف لا يقبل التنوين", "ولا يُجرّ بالكسرة بل بالفتحة نيابة عنها", "مثل: برامجَ، فلسطينَ"]], ["حالات المنع (1)", ["مختوم بهمزة تأنيث بعد ألف مد: صحراء", "صيغة منتهى الجموع: مرافق، مطافئ", "صفة على وزن أفعل: أحمر، أخضر"]], ["حالات المنع (2)", ["صفة على وزن فعلان/فعلى: سهران، حبلى", "صفة أو اسم بألف تأنيث مقصورة: حبلى", "علم مؤنث: غزّة، زينب"]], ["حالات منع الأعلام", ["علم بألف ونون زائدتين: رضوان", "علم مركب مزجي: بور سعيد", "علم أعجمي فوق ثلاثة حروف: موريس", "علم على وزن الفعل: أحمد، أو وزن فُعَل: عمر"]], ["كيف أطبّق؟", ["أنظر إن كان مجرورًا بلا تنوين", "أسأل: هل يدخل في الحالات؟", "أعربه: مجرور بالفتحة نيابة عن الكسرة"]], ["أخطاء شائعة", ["تنوينه أو كسره عند الجر", "عدّ جمع المؤنث السالم ممنوعًا مثل طوّافات (مصروف)", "إن أُضيف أو دخلته «أل» جُرّ بالكسرة"]]], "K": "الممنوع من الصرف لا يُنوَّن ويُجَرّ بالفتحة نيابة عن الكسرة، إلا إذا أضيف أو عُرِّف بأل.", "M": ["احفظ حالات المنع واربط كل حالة بمثال", "في الجر: «مجرور وعلامة جره الفتحة نيابة عن الكسرة»", "اذكر علة المنع في الإعراب", "جمع المؤنث السالم مصروف"], "X": "بعض الكلمات لا تأخذ تنوينًا ولا كسرة في آخرها لأنها تشبه الفعل في بعض صفاتها. نقول: مررتُ بغزةَ، وليس بغزةٍ. أما إذا أُضيفت الكلمة أو دخلت عليها «أل» فنجرها بالكسرة كالعادة.", "EX": [["بيّن علة منع: رضوان، بور سعيد، أحمد، موريس، زينب، عمر.", "رضوان: علم بألف ونون زائدتين. بور سعيد: علم مركب مزجي. أحمد: علم على وزن الفعل. موريس: علم أعجمي فوق ثلاثة أحرف. زينب: علم مؤنث. عمر: علم على وزن فُعَل."], ["أعرب ما تحته خط: ساعد الأطباء إخوانهم في غزَّةَ.", "في: حرف جر. غزةَ: اسم مجرور بفي وعلامة جره الفتحة نيابة عن الكسرة لأنه ممنوع من الصرف (علم مؤنث)."], ["استخرج الممنوع من الصرف: مطافئ، طوّافات، زلازل، سهران، حضرموت.", "مطافئ: صيغة منتهى الجموع. زلازل: صيغة منتهى الجموع. سهران: صفة على وزن فعلان. حضرموت: علم مركب مزجي. طوّافات: جمع مؤنث سالم فهو مصروف."]]}, {"m": 3, "w": 3, "t": "الظاهرة اللغوية: التوكيد اللفظي والتوكيد المعنوي", "pg": "ص 58", "i": "🔁", "B": [["التوكيد المعنوي", ["بألفاظ: نفس، عين، كل، جميع، عامة", "تضاف إلى ضمير يعود على المؤكَّد", "وتطابقه في النوع والعدد"]], ["التوكيد اللفظي", ["تكرار الكلمة نفسها أو مرادفها مباشرة", "الثانية تسمى توكيدًا لفظيًّا", "يتبع المؤكَّد في الإعراب"]], ["الإعراب", ["التوكيد من التوابع", "يأخذ إعراب المؤكَّد رفعًا أو نصبًا أو جرًّا", "الضمير المتصل بالتوكيد مضاف إليه"]], ["فائدة التوكيد", ["تقوية المعنى وإزالة الشك", "شمول الجميع بكلّ وجميع", "التنبيه والتأكيد بتكرار الكلمة"]], ["كيف أميّز؟", ["هل تكررت الكلمة نفسها؟ فهو لفظي", "هل جاءت «كل، نفس، ذات...» مع ضمير؟ فهو معنوي", "ثم أعرب حسب موقع المؤكَّد"]], ["أخطاء شائعة", ["نسيان الضمير المطابق للمؤكَّد", "إعراب «كل» مبتدأ وهي توكيد بعد اسم", "إعرابها بغير إعراب المؤكَّد"]]], "K": "التوكيد تابع يقوّي معنى ما قبله: لفظي بتكرار الكلمة، ومعنوي بألفاظ مثل كلّ ونفس مضافة إلى ضمير مطابق.", "M": ["اللفظي: تكرار مباشر للكلمة أو مرادفها", "المعنوي: لفظ التوكيد 