النصر.", "EX": [["لماذا يعد النص حواريا رغم أن الجزائر لا ترد؟", "الكاتب يخاطب الجزائر بالنداء والسؤال. يقول لها: هل تسمعينني. هذه قرائن لحوار أحد طرفيه المتكلم والآخر الجزائر المخاطبة."], ["ما وظيفة تكرار النداء «أيتها الجزائر»؟", "التكرار يبقي الجزائر حاضرة في الخطاب. يقوي العاطفة. ويربط فقرات النص بعضها ببعض."]]}, {"m": 8, "w": 2, "t": "فهم المكتوب: شوق وحنين إلى الوطن", "pg": "", "i": "🌹", "B": [["التعريف بالنص", ["الشاعر: إيليا أبو ماضي (1889-1957)، شاعر عربي لبناني", "من شعراء المهجر ومؤسسي الرابطة القلمية مع جبران ونعيمة"]], ["الفكرة العامة", ["شاعر مغترب يحن إلى لبنان ويرى أن الغربة غربة الروح"]], ["الأفكار الأساسية", ["حزن خفي تحت ضحكة ظاهرة والأعوام تمر", "الغربة الحقيقية غربة الروح لا الأجساد", "تشبيه نفسه بالسوسن والشمس لأنه انتقل بعيدا", "حنين لبنان والغوطة ودعاء بالعودة", "نصح الدعاة: الأرض التي ينام أهلها تُغتصب"]], ["المفردات", ["الورى: الناس، النوى: الغربة والبعد عن الأحباب", "الدجى: سواد الليل، الكعاب: الفتاة البالغة"]], ["القيم", ["حب الوطن، الانتماء، اليقظة لحماية الأرض"]], ["النمط والانسجام", ["وصفي وسردي ثم توجيهي في الأبيات الأخيرة", "ضمير المتكلم أنا يهيمن، والنفي والاستدراك والتقابل يقوّيان المعنى"]]], "K": "الغربة الحقيقية في نظر الشاعر غربة الروح والشوق، وأهل الأرض إن غفلوا عنها اغتُصبت.", "M": ["لا شكوى من البعد الجسدي، فالمهم ارتباط القلب بالوطن", "ضمير «أنا» يرمز إلى الشاعر ويربط الأبيات", "التقابل: ضحك ظاهر وحزن في الداخل", "التوجيه يظهر في دعوة الأهل ألا يناموا عن أرضهم"], "X": "الشاعر يعيش بعيدا عن لبنان، ويقول إن بعد الجسد ليس أصعب غربة، بل أصعبها بعد القلب. ثم ينصح أهل كل أرض أن يسهروا عليها كي لا تُسلب.", "EX": [["اشرح باختصار: «غربة الأجسام ليست باغتراب».", "الشاعر يرى أن بعد الجسد عن الوطن ليس اغترابا حقيقيا. الاغتراب الحقيقي ضعف الصلة بالوطن. فمن بقي قلبه مع أرضه ليس غريبا."], ["بين التقابل في النص.", "الشاعر يضحك للناس وهو حزين وحده. الأول حال ظاهرة والثاني حال داخلية. التقابل يبرز شدة معاناته."]]}, {"m": 8, "w": 3, "t": "الظاهرة اللغوية: الجملة الواقعة جوابا لشرط (1): أسلوب الشرط وأدواته", "pg": "ص 152", "i": "✍️", "B": [["أس